def two_sum(nums: list[int], target: int) -> list[int]:
    """
    Find two indices such that nums[i] + nums[j] == target.
    Indices are returned in ascending order and each element is used at most once.
    """
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            j = seen[complement]
            return [j, i] if j < i else [i, j]
        seen[num] = i
    raise ValueError("No two-sum solution found")

def is_valid_parentheses(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    for char in s:
        if char in opens:
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
        else:
            # ignore any other characters (though per spec there shouldn't be any)
            pass
    return not stack

